-- Baseline: the live app's schema as of 30 Oct 2026, so beta starts identical to production.
-- Generated by concatenating supabase-setup.sql, supabase-multi-business.sql and supabase-pricing.sql
-- (in the order they were run on production) without their begin/commit lines.
-- Typed tables for the rebuild arrive in later migrations (specs/REBUILD-PLAN.md, stage 2).

-- ==================== supabase-setup.sql ====================
-- Run once in Supabase: SQL Editor → New query → paste → Run.

-- All app records (clients, systems, units, jobs, materials, invoices, reports, settings)
create table if not exists public.docs (
  col text not null,
  id text not null,
  data jsonb not null default '{}'::jsonb,
  updated_at timestamptz not null default now(),
  primary key (col, id)
);
alter table public.docs replica identity full;
alter table public.docs enable row level security;

drop policy if exists "signed-in users can read" on public.docs;
drop policy if exists "signed-in users can write" on public.docs;
create policy "signed-in users can read" on public.docs for select to authenticated using (true);
create policy "signed-in users can write" on public.docs for all to authenticated using (true) with check (true);

create or replace function public.touch_updated_at() returns trigger language plpgsql as $$
begin new.updated_at = now(); return new; end $$;
drop trigger if exists docs_touch on public.docs;
create trigger docs_touch before update on public.docs for each row execute function public.touch_updated_at();

-- Live sync between phone and laptop
do $$ begin
  alter publication supabase_realtime add table public.docs;
exception when duplicate_object then null; end $$;

-- Private bucket for job photos
insert into storage.buckets (id, name, public) values ('photos', 'photos', false)
on conflict (id) do nothing;
drop policy if exists "signed-in users manage photos" on storage.objects;
create policy "signed-in users manage photos" on storage.objects for all to authenticated
  using (bucket_id = 'photos') with check (bucket_id = 'photos');

-- ==================== supabase-multi-business.sql ====================
-- Air Ledger: let other businesses sign up.
-- Run ONCE in Supabase: SQL Editor → New query → paste → Run.
-- Safe to re-run. On the first run, existing records and photos are moved into one
-- business ("Altitude Climate") and every existing user becomes its owner and an Air Ledger admin.
-- Take a backup first: in the app, Settings → Download full backup (JSON).


-- ---------- businesses, members, invites ----------
create table if not exists public.orgs (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  slug text unique,
  logo_url text,
  created_by uuid references auth.users on delete set null,
  created_at timestamptz not null default now()
);

create table if not exists public.members (
  org_id uuid not null references public.orgs on delete cascade,
  user_id uuid not null references auth.users on delete cascade,
  email text,
  role text not null default 'member' check (role in ('owner','member')),
  created_at timestamptz not null default now(),
  primary key (org_id, user_id)
);

-- org_id null = a code that lets someone create a NEW business.
-- org_id set  = a code that lets someone JOIN that business.
create table if not exists public.invites (
  code text primary key,
  org_id uuid references public.orgs on delete cascade,
  email text,
  created_by uuid references auth.users on delete set null,
  created_at timestamptz not null default now(),
  used_by uuid references auth.users on delete set null,
  used_at timestamptz
);

create table if not exists public.platform_admins (
  user_id uuid primary key references auth.users on delete cascade
);

-- One row of app-wide settings.
create table if not exists public.platform (
  id boolean primary key default true check (id),
  require_invite boolean not null default true,
  legacy_org uuid references public.orgs on delete set null
);
insert into public.platform (id) values (true) on conflict do nothing;

-- ---------- helpers (security definer so policies don't recurse) ----------
create or replace function public.my_org_ids() returns setof uuid
language sql stable security definer set search_path = public as $$
  select org_id from public.members where user_id = auth.uid()
$$;

create or replace function public.is_owner(p_org uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select exists(select 1 from public.members where org_id = p_org and user_id = auth.uid() and role = 'owner')
$$;

create or replace function public.my_owned_org_ids() returns setof uuid
language sql stable security definer set search_path = public as $$
  select org_id from public.members where user_id = auth.uid() and role = 'owner'
$$;

create or replace function public.is_platform_admin() returns boolean
language sql stable security definer set search_path = public as $$
  select exists(select 1 from public.platform_admins where user_id = auth.uid())
$$;

create or replace function public.slugify(p text) returns text
language sql immutable as $$
  select coalesce(nullif(trim(both '-' from regexp_replace(lower(coalesce(p,'')), '[^a-z0-9]+', '-', 'g')), ''), 'business')
$$;

create or replace function public.unique_slug(p text, p_org uuid default null) returns text
language plpgsql stable security definer set search_path = public as $$
declare base text := left(public.slugify(p), 40); s text := base; n int := 1;
begin
  while exists(select 1 from public.orgs where slug = s and id is distinct from p_org) loop
    n := n + 1; s := base || '-' || n;
  end loop;
  return s;
end $$;

-- ---------- move existing data into the first business ----------
do $$
declare v_org uuid;
begin
  select legacy_org into v_org from public.platform;
  if v_org is null then
    insert into public.orgs (name, slug) values ('Altitude Climate', 'altitude-climate') returning id into v_org;
    update public.platform set legacy_org = v_org;
    -- First run only: everyone who can sign in today owns the existing data.
    insert into public.members (org_id, user_id, email, role)
      select v_org, u.id, u.email, 'owner' from auth.users u
      on conflict do nothing;
    insert into public.platform_admins (user_id) select id from auth.users on conflict do nothing;
  end if;

  if not exists (select 1 from information_schema.columns where table_schema='public' and table_name='docs' and column_name='org_id') then
    alter table public.docs add column org_id uuid references public.orgs on delete cascade;
  end if;
  update public.docs set org_id = v_org where org_id is null;
end $$;

alter table public.docs alter column org_id set not null;
alter table public.docs drop constraint if exists docs_pkey;
alter table public.docs add primary key (org_id, col, id);

-- ---------- row-level security ----------
alter table public.orgs enable row level security;
alter table public.members enable row level security;
alter table public.invites enable row level security;
alter table public.platform_admins enable row level security;
alter table public.platform enable row level security;

drop policy if exists "signed-in users can read" on public.docs;
drop policy if exists "signed-in users can write" on public.docs;
drop policy if exists "members read their business" on public.docs;
drop policy if exists "members write their business" on public.docs;
create policy "members read their business" on public.docs for select to authenticated
  using (org_id in (select public.my_org_ids()));
create policy "members write their business" on public.docs for all to authenticated
  using (org_id in (select public.my_org_ids())) with check (org_id in (select public.my_org_ids()));

drop policy if exists "members see their business" on public.orgs;
drop policy if exists "owners edit their business" on public.orgs;
create policy "members see their business" on public.orgs for select to authenticated
  using (id in (select public.my_org_ids()));
create policy "owners edit their business" on public.orgs for update to authenticated
  using (public.is_owner(id)) with check (public.is_owner(id));

drop policy if exists "members see their team" on public.members;
drop policy if exists "owners remove team members" on public.members;
create policy "members see their team" on public.members for select to authenticated
  using (org_id in (select public.my_org_ids()));
create policy "owners remove team members" on public.members for delete to authenticated
  using (public.is_owner(org_id) and user_id <> auth.uid());

drop policy if exists "owners and admins see invites" on public.invites;
drop policy if exists "owners and admins delete invites" on public.invites;
create policy "owners and admins see invites" on public.invites for select to authenticated
  using ((org_id is null and public.is_platform_admin()) or public.is_owner(org_id));
create policy "owners and admins delete invites" on public.invites for delete to authenticated
  using (used_by is null and ((org_id is null and public.is_platform_admin()) or public.is_owner(org_id)));

drop policy if exists "admins see themselves" on public.platform_admins;
create policy "admins see themselves" on public.platform_admins for select to authenticated
  using (user_id = auth.uid());

drop policy if exists "anyone reads platform" on public.platform;
drop policy if exists "admins edit platform" on public.platform;
create policy "anyone reads platform" on public.platform for select to anon, authenticated using (true);
create policy "admins edit platform" on public.platform for update to authenticated
  using (public.is_platform_admin()) with check (public.is_platform_admin());

-- ---------- functions the app calls ----------
-- Public: business name + logo for a branded sign-in page.
create or replace function public.org_public(p_slug text) returns table (name text, slug text, logo_url text)
language sql stable security definer set search_path = public as $$
  select name, slug, logo_url from public.orgs where slug = lower(p_slug)
$$;

-- Public: what an invite code is for (without revealing anything else).
create or replace function public.invite_info(p_code text) returns table (valid boolean, joins boolean, org_name text)
language sql stable security definer set search_path = public as $$
  select true, i.org_id is not null, o.name
  from public.invites i left join public.orgs o on o.id = i.org_id
  where i.code = upper(trim(p_code)) and i.used_by is null
$$;

create or replace function public.create_invite(p_org uuid default null, p_email text default null) returns text
language plpgsql security definer set search_path = public as $$
declare v_code text;
begin
  if auth.uid() is null then raise exception 'Please sign in'; end if;
  if p_org is null and not public.is_platform_admin() then raise exception 'Only Air Ledger admins can invite new businesses'; end if;
  if p_org is not null and not public.is_owner(p_org) then raise exception 'Only the business owner can invite people'; end if;
  v_code := upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 10));
  insert into public.invites (code, org_id, email, created_by) values (v_code, p_org, nullif(lower(trim(p_email)), ''), auth.uid());
  return v_code;
end $$;

create or replace function public.create_business(p_name text, p_code text default null) returns uuid
language plpgsql security definer set search_path = public as $$
declare v_org uuid; v_inv public.invites; v_req boolean;
begin
  if auth.uid() is null then raise exception 'Please sign in'; end if;
  if coalesce(trim(p_name), '') = '' then raise exception 'Please enter your business name'; end if;
  select require_invite into v_req from public.platform;
  if p_code is not null and trim(p_code) <> '' then
    select * into v_inv from public.invites where code = upper(trim(p_code)) and used_by is null and org_id is null for update;
    if not found then raise exception 'That invite code isn''t valid or has already been used'; end if;
  elsif v_req and not public.is_platform_admin() then
    raise exception 'You need an invite code to create a business';
  end if;
  insert into public.orgs (name, slug, created_by) values (trim(p_name), public.unique_slug(p_name), auth.uid()) returning id into v_org;
  insert into public.members (org_id, user_id, email, role) values (v_org, auth.uid(), auth.jwt()->>'email', 'owner');
  if v_inv.code is not null then update public.invites set used_by = auth.uid(), used_at = now() where code = v_inv.code; end if;
  return v_org;
end $$;

create or replace function public.join_business(p_code text) returns uuid
language plpgsql security definer set search_path = public as $$
declare v_inv public.invites;
begin
  if auth.uid() is null then raise exception 'Please sign in'; end if;
  select * into v_inv from public.invites where code = upper(trim(p_code)) and used_by is null and org_id is not null for update;
  if not found then raise exception 'That invite code isn''t valid or has already been used'; end if;
  if v_inv.email is not null and v_inv.email <> lower(auth.jwt()->>'email') then
    raise exception 'This invite was sent to a different email address';
  end if;
  insert into public.members (org_id, user_id, email, role) values (v_inv.org_id, auth.uid(), auth.jwt()->>'email', 'member')
    on conflict do nothing;
  update public.invites set used_by = auth.uid(), used_at = now() where code = v_inv.code;
  return v_inv.org_id;
end $$;

create or replace function public.update_business(p_org uuid, p_name text, p_slug text, p_logo_url text) returns text
language plpgsql security definer set search_path = public as $$
declare v_slug text;
begin
  if not public.is_owner(p_org) then raise exception 'Only the business owner can change this'; end if;
  v_slug := public.slugify(coalesce(nullif(trim(p_slug), ''), p_name));
  if exists(select 1 from public.orgs where slug = v_slug and id <> p_org) then raise exception 'That sign-in link is already taken'; end if;
  update public.orgs set name = coalesce(nullif(trim(p_name), ''), name), slug = v_slug, logo_url = p_logo_url where id = p_org;
  return v_slug;
end $$;

create or replace function public.make_owner(p_org uuid, p_user uuid) returns void
language plpgsql security definer set search_path = public as $$
begin
  if not public.is_owner(p_org) then raise exception 'Only the business owner can change this'; end if;
  update public.members set role = 'owner' where org_id = p_org and user_id = p_user;
end $$;

-- Deletes a business and all of its records, team and invites.
-- The app removes its photos and logo through the storage API first.
create or replace function public.delete_business(p_org uuid) returns void
language plpgsql security definer set search_path = public as $$
begin
  if not public.is_owner(p_org) then raise exception 'Only the business owner can delete it'; end if;
  delete from public.orgs where id = p_org;
end $$;

-- Businesses that will be deleted along with the signed-in user's account
-- (ones where they're the only member). Fails if they're the only owner of a business that has a team.
create or replace function public.account_deletion_plan() returns table (org_id uuid, name text)
language plpgsql stable security definer set search_path = public as $$
declare r record;
begin
  if auth.uid() is null then raise exception 'Please sign in'; end if;
  for r in select o.id, o.name from public.orgs o join public.members m on m.org_id = o.id
           where m.user_id = auth.uid() and m.role = 'owner'
             and not exists(select 1 from public.members x where x.org_id = o.id and x.role = 'owner' and x.user_id <> auth.uid()) loop
    if exists(select 1 from public.members x where x.org_id = r.id and x.user_id <> auth.uid()) then
      raise exception 'You''re the only owner of %. Make someone else in the team an owner, or delete the business, first.', r.name;
    end if;
    org_id := r.id; name := r.name; return next;
  end loop;
end $$;

create or replace function public.delete_my_account() returns void
language plpgsql security definer set search_path = public, auth as $$
begin
  delete from public.orgs where id in (select p.org_id from public.account_deletion_plan() p);
  delete from public.platform_admins where user_id = auth.uid();
  delete from auth.users where id = auth.uid();
end $$;

revoke all on function public.create_invite(uuid, text), public.create_business(text, text),
  public.join_business(text), public.update_business(uuid, text, text, text), public.make_owner(uuid, uuid),
  public.delete_business(uuid), public.account_deletion_plan(), public.delete_my_account() from public, anon;
grant execute on function public.create_invite(uuid, text), public.create_business(text, text),
  public.join_business(text), public.update_business(uuid, text, text, text), public.make_owner(uuid, uuid),
  public.delete_business(uuid), public.account_deletion_plan(), public.delete_my_account() to authenticated;
grant execute on function public.org_public(text), public.invite_info(text) to anon, authenticated;

-- ---------- photos: each business only sees its own folder ----------
-- New photos are saved as <business id>/<file>. Photos from before this
-- change have no folder and stay visible to the first business only.
drop policy if exists "signed-in users manage photos" on storage.objects;
drop policy if exists "members manage their photos" on storage.objects;
create policy "members manage their photos" on storage.objects for all to authenticated
  using (bucket_id = 'photos' and (
    (storage.foldername(name))[1] in (select org_id::text from public.my_org_ids() org_id)
    or (position('/' in name) = 0 and (select legacy_org from public.platform) in (select public.my_org_ids()))))
  with check (bucket_id = 'photos' and (storage.foldername(name))[1] in (select org_id::text from public.my_org_ids() org_id));

-- Logos are public (they show on the sign-in page), but only owners can change them.
insert into storage.buckets (id, name, public) values ('logos', 'logos', true)
on conflict (id) do update set public = true;
drop policy if exists "owners manage their logo" on storage.objects;
create policy "owners manage their logo" on storage.objects for all to authenticated
  using (bucket_id = 'logos' and (storage.foldername(name))[1] in (select org_id::text from public.my_owned_org_ids() org_id))
  with check (bucket_id = 'logos' and (storage.foldername(name))[1] in (select org_id::text from public.my_owned_org_ids() org_id));


-- ==================== supabase-pricing.sql ====================
-- Air Ledger: keep prices and invoices to business owners.
-- Run ONCE in Supabase, after supabase-multi-business.sql: SQL Editor → New query → paste → Run. Safe to re-run.
-- Engineers (team members who aren't owners) can still read and write clients, assets, jobs, materials and reports,
-- but can't read or change anything in the "pricing" or "invoices" collections.
-- The app moves existing prices into "pricing" the next time an owner opens it.


create or replace function public.can_use_doc(p_org uuid, p_col text) returns boolean
language sql stable security definer set search_path = public as $$
  select p_org in (select public.my_org_ids())
     and (p_col not in ('pricing','invoices') or public.is_owner(p_org))
$$;

drop policy if exists "members read their business" on public.docs;
drop policy if exists "members write their business" on public.docs;
create policy "members read their business" on public.docs for select to authenticated
  using (public.can_use_doc(org_id, col));
create policy "members write their business" on public.docs for all to authenticated
  using (public.can_use_doc(org_id, col)) with check (public.can_use_doc(org_id, col));

